                input[1] = false
                input[2] = false
                input[3] = false
                input[4] = false
                input[5] = false
                """
            }
        }
        then {
            assertAll(
                { assert workflow.success},
                { assert snapshot(sanitizeOutput(workflow.out)).match() }
            )
        }
    }

    test("sarscov2 - fastq - paired_end - stub") {

        options "-stub"

        when {
            workflow {
                """
                input[0] = channel.of([
                    [ id:'test_paired', single_end:false ], // meta map
